import assert from 'node:assert/strict'
if(!process.argv.includes('--synthetic-only'))throw new Error('Explicit fictional fixture flag required')
const origin='http://127.0.0.1:3167',backend='http://127.0.0.1:3166'
const post=(body,extra={})=>fetch(`${origin}/api/marketing/leads`,{method:'POST',headers:{origin,'Content-Type':'application/json',...extra},body:typeof body==='string'?body:JSON.stringify(body)})
const valid={email:'http-fixture@example.test',consent:true,website:''}
const page=await fetch(origin);assert.equal(page.status,200);const html=await page.text()
assert.match(html,/Make room/);assert.match(html,/\$1\.99/);assert.match(html,/\$19\.99/)
for(const id of ['features','pricing','faq','updates'])assert.ok(html.includes(`id="${id}"`))
for(const route of ['/sign-in','/sign-up'])assert.equal((await fetch(origin+route)).status,200)
assert.equal((await post(valid,{origin:'https://foreign.example'})).status,403)
assert.equal((await post(valid,{'Content-Type':'text/plain'})).status,415)
assert.equal((await post('{broken')).status,400)
assert.equal((await post({...valid,consent:false})).status,400)
assert.equal((await post({...valid,note:'must not collect private notes'})).status,400)
assert.equal((await post({...valid,website:'x'.repeat(2200)})).status,413)
const getCounts=async()=>await(await fetch(`${backend}/fixture-counts`,{headers:{authorization:'Bearer synthetic-marketing-service'}})).json()
const before=await getCounts()
const trap=await post({...valid,website:'bot.example'});assert.equal(trap.status,200)
assert.deepEqual(await getCounts(),before)
const a=await post(valid),b=await post(valid)
assert.equal(a.status,200);assert.equal(b.status,200);assert.deepEqual(await a.json(),await b.json())
const after=await getCounts();assert.equal(after.leads,before.leads+1);assert.equal(after.notified,0)
const attempts=await Promise.all(Array.from({length:12},(_,i)=>post({...valid,email:`burst-${i}@example.test`})))
assert.equal(attempts.filter(r=>r.status===200).length,8)
assert.equal(attempts.filter(r=>r.status===429).length,4)
assert.equal((await fetch(`${backend}/rest/v1/marketing_leads`,{headers:{authorization:'Bearer synthetic-marketing-anon'}})).status,403)
console.log('Local marketing HTTP/real-SQL smoke passed: page/prices/auth links, honeypot, dedupe, consent/body/origin guards, concurrent IP quota, no public lead reads, notifications remain off.')
